import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int fish = sc.nextInt();

        int bags = fish / 3;
        int left = fish % 3;

        System.out.println("装满 " + bags + " 袋喵");
        System.out.println("还剩 " + left + " 条喵");
        System.out.println("装好的这些能卖 " + bags * 2 + " 元喵");
    }
}

